/** Public install proof for the decisions guide ownership transfer, including inherited content and history. */
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import {
  cpSync,
  existsSync,
  mkdirSync,
  readFileSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { getTemplatePath } from "../../src/cli/paths.js";
import {
  canonicalManagedInstallStateBytes,
  type ManagedInstallStateV2,
} from "../../src/cli/managed-setup-state.js";
import {
  makeTempProject,
  PROJECT_ROOT,
  recordStaleBaselineHashes,
  runCliInstaller,
  runInstaller,
  symlinkFileOrSkip,
} from "./setup-install.helpers.js";

const GUIDE = ".goat-flow/learning-loop/decisions/README.md";
const LEGACY_GUIDE = ".goat-flow/decisions/README.md";
const STATE = ".goat-flow/state/install/managed.json";
const TEMPLATE = "workflow/setup/reference/decisions-readme.md";
// Exact released bytes from v1.17.0:workflow/setup/reference/decisions-readme.md; embedded so tests need no tags or network.
const RELEASED_GUIDE =
  '# Decisions\n\nArchitectural Decision Records (ADRs) capture durable decisions that constrain future work. They are not task notes, TODO lists, bug reports, benchmark dumps, or confirmations that nothing changed.\n\n> If the choice does not outlast the feature branch, it is not an ADR.\n\n## Generated Index\n\n`INDEX.md` in this directory is generated by `goat-flow index` - never edit it by hand. After adding, editing, renaming, or resolving entries, re-run `goat-flow index`; `goat-flow stats --check` fails while the index is stale.\n\n## Automatic Capture Policy\n\nManual edits are normal: an explicit request to add or update a durable learning-loop entry means edit the Markdown in the correct directory. Programmatic automatic capture from terminal sessions, quality reports, PR reviews, or agent output is disabled unless `.goat-flow/config.yaml` explicitly sets `learning-loop.auto-capture.enabled: true` and a CLI-owned writer for that target exists. Prompts may suggest an ADR candidate, but automatic durable writes belong to CLI-owned code after opt-in.\n\nAuto-capture candidates must follow Extract / Consolidate / Skip:\n\n- Extract only when the item changes a future READ/SCOPE/ACT/VERIFY decision.\n- Consolidate into an existing ADR when the same durable decision already exists.\n- Skip raw tool output, successful smoke runs, UI/deploy churn, chain-of-thought, screenshots, raw JSON/HTML, duplicate dumps, and "I read the docs" summaries.\n\n## When To Write An ADR\n\nWrite an ADR when the decision:\n\n- changes the system structure, public contract, deployment model, data model, security model, or long-term workflow;\n- constrains future implementation choices in a way another maintainer will need to understand;\n- reverses, supersedes, or materially narrows an earlier decision;\n- resolves a non-obvious trade-off with real evidence; or\n- documents a durable exception that future agents might otherwise "fix" incorrectly.\n\nDo not write an ADR for routine implementation details, temporary workarounds, benchmark traces, local debugging notes, or "we kept the existing behavior" confirmations.\n\n## Wrong Home -> Right Home\n\n| Note type | Correct home |\n| --- | --- |\n| Implementation TODO, checklist, milestone, or scoped plan | `.goat-flow/plans/` or the issue tracker |\n| Reproducible hazard, trap, or recurring failure with measured evidence | `.goat-flow/learning-loop/footguns/` |\n| Reusable takeaway from a completed fix or verification failure | `.goat-flow/learning-loop/lessons/` |\n| Temporary scratch note, benchmark trace, raw command output, or local hypothesis | `.goat-flow/scratchpad/` |\n| Backlog request, product question, or work that needs prioritisation | Linear/GitHub issue |\n| Durable architecture, policy, contract, or trade-off decision | `.goat-flow/learning-loop/decisions/ADR-NNN-kebab-case-title.md` |\n\n## Naming\n\nADR files must be named `ADR-NNN-kebab-case-title.md`, for example `ADR-001-cache-signature-policy.md`.\n\nAllowed non-ADR files: `README.md` and `INDEX.md`.\n\nEverything else in this directory is a stats failure. If a note cannot earn an ADR filename, route it using the table above.\n\n## Required Structure\n\nEvery ADR carries `**Status:**`, `**Date:**`, `## Context`, `## Decision`, and at least one trade-off section: `## Consequences`, `## Failure Mode Comparison`, or `## Reversibility`. The template below is the recommended full shape, not the minimum:\n\n```markdown\n# ADR-NNN: Title\n\n**Status:** Accepted\n**Date:** YYYY-MM-DD\n\n## Decision\n\nWhat was decided. Be specific enough that someone can verify whether the codebase conforms.\n\n## Context\n\nWhy this decision exists. Cite real incidents, constraints, measurements, or prior decisions.\n\n## Failure Mode Comparison\n\n| Option | What fails | Why rejected or accepted |\n| --- | --- | --- |\n| ... | ... | ... |\n\n## Reversibility\n\nWhether this is a one-way or two-way door, plus rollback or revisit triggers.\n```\n\n`## Context` may appear before `## Decision` if that reads better. Section order is not enforced.\n\nADR narrative (`## Context`, `## Decision`, and trade-off prose) follows `.goat-flow/skill-docs/playbooks/writing-human-facing-prose.md`. Body prose only - status/date metadata lines, comparison tables, and the filename format stay exempt as fixed schema.\n\nAt least one trade-off section is required:\n\n- `## Consequences`\n- `## Failure Mode Comparison`\n- `## Reversibility`\n\nRecommended metadata:\n\n- `**Author(s):**`\n- `**Ticket/Context:**`\n- `**Updated:** YYYY-MM-DD` when amending an accepted ADR\n\n## Status Values\n\n- `Proposed` - under discussion, not yet binding\n- `Accepted` - decision made, implementation may still be underway\n- `Implemented` - decision is reflected in the codebase\n- `Superseded by ADR-NNN` - replaced by a later decision\n\n## Anti-Patterns\n\nDo not create ADRs for:\n\n- no-op confirmations, such as "we kept the existing threshold";\n- TODOs disguised as decisions;\n- workaround notes for a missing implementation;\n- scoping notes that belong in a milestone file;\n- benchmark traces without a durable decision;\n- files missing the `ADR-NNN-...` filename, `**Status:**`, `**Date:**`, `## Context`, `## Decision`, or a trade-off section.\n\n## Before Writing\n\nCheck all five before creating a file here:\n\n- The decision will still matter after the current task closes.\n- The decision constrains future choices or explains a non-obvious trade-off.\n- The evidence is real and cited in the ADR.\n- The file can honestly use an `ADR-NNN-kebab-case-title.md` name.\n- The note does not belong in tasks, footguns, lessons, scratchpad, or the issue tracker.\n\nIf any check fails, do not write an ADR. Route the note to the correct home. If you are an AI agent and cannot decide, ask a human before creating a file in this directory.\n';
const CUSTOM_GUIDE =
  RELEASED_GUIDE +
  "\n## Project decision process\n\nKeep the team's approval checklist.\n";

/** Seed a previously user-owned guide, with optional legacy history that never recorded its hash. */
function inheritedTarget(
  content: string,
  history: boolean,
  guidePath = GUIDE,
): string {
  const root = makeTempProject();
  mkdirSync(dirname(join(root, guidePath)), { recursive: true });
  writeFileSync(join(root, guidePath), content);
  if (history) {
    const path = join(root, ".goat-flow/state/install/claude.json");
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(
      path,
      JSON.stringify(
        {
          schemaVersion: "goat-flow.install-state.v1",
          agent: "claude",
          goatFlowVersion: "1.17.0",
          files: [],
        },
        null,
        2,
      ) + "\n",
    );
  }
  return root;
}

/** Read the persisted state after a successful public install. */
function state(root: string): ManagedInstallStateV2 {
  return JSON.parse(readFileSync(join(root, STATE), "utf8"));
}

/** Run the real preview and return the guide row; refusal remains an assertion failure. */
function guidePreview(root: string, ...flags: string[]) {
  const result = runCliInstaller(
    root,
    "--agent",
    "claude",
    "--dry-run",
    "--format",
    "json",
    ...flags,
  );
  assert.equal(result.status, 0, result.stdout + result.stderr);
  const preview = JSON.parse(result.stdout);
  const row = preview.files.find(
    (file: { path: string }) => file.path === GUIDE,
  );
  assert.ok(row);
  return row;
}

/** Apply through the public CLI and retain its closing text for user-visible claims. */
function apply(root: string, ...flags: string[]): string {
  const result = runCliInstaller(root, "--agent", "claude", ...flags);
  assert.equal(result.status, 0, result.stdout + result.stderr);
  return result.stdout;
}

describe("decisions guide ownership transfer", () => {
  it("refreshes the exact released guide missing from legacy history", () => {
    assert.equal(
      createHash("sha256").update(RELEASED_GUIDE).digest("hex"),
      "76b2f239b4f80bda387c48429860a6cc3b3ca7b591e2ced174ae3207feb30b50",
    );
    const root = inheritedTarget(RELEASED_GUIDE, true);
    assert.equal(guidePreview(root).action, "replace");
    apply(root);
    assert.equal(
      readFileSync(join(root, GUIDE), "utf8"),
      readFileSync(getTemplatePath(TEMPLATE), "utf8"),
    );
    assert.ok(state(root).files.some((row) => row.path === GUIDE));
    assert.equal(state(root).receipts.length, 1);
  });

  it("preserves a legacy-folder custom guide through migration and repeat apply until named adoption", () => {
    const root = inheritedTarget(CUSTOM_GUIDE, false, LEGACY_GUIDE);
    const row = guidePreview(root, "--force-managed");
    assert.equal(row.state, "local-preserved");
    assert.equal(row.currentStatus, "missing");
    assert.equal(existsSync(join(root, GUIDE)), false);
    assert.equal(readFileSync(join(root, LEGACY_GUIDE), "utf8"), CUSTOM_GUIDE);
    assert.match(
      apply(root, "--force-managed"),
      /No new full-install receipt/u,
    );
    assert.equal(existsSync(join(root, LEGACY_GUIDE)), false);
    assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
    assert.equal(
      state(root).files.some((file) => file.path === GUIDE),
      false,
    );
    assert.equal(state(root).receipts.length, 0);
    const before = readFileSync(join(root, STATE), "utf8");
    apply(root);
    assert.equal(readFileSync(join(root, STATE), "utf8"), before);
    assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
    apply(root, "--force-path", GUIDE);
    assert.equal(
      readFileSync(join(root, GUIDE), "utf8"),
      readFileSync(getTemplatePath(TEMPLATE), "utf8"),
    );
    assert.equal(state(root).receipts.length, 1);
  });

  for (const [label, content] of [
    ["released", RELEASED_GUIDE],
    ["current package", readFileSync(getTemplatePath(TEMPLATE), "utf8")],
  ]) {
    it(`refreshes a ${label} guide inherited from the legacy folder`, () => {
      const root = inheritedTarget(content, false, LEGACY_GUIDE);
      assert.equal(guidePreview(root).action, "create");
      assert.doesNotMatch(apply(root), /No new full-install receipt/u);
      assert.equal(existsSync(join(root, LEGACY_GUIDE)), false);
      assert.equal(
        readFileSync(join(root, GUIDE), "utf8"),
        readFileSync(getTemplatePath(TEMPLATE), "utf8"),
      );
      assert.ok(state(root).files.some((row) => row.path === GUIDE));
      assert.equal(state(root).receipts.length, 1);
    });
  }

  for (const history of [false, true]) {
    it(`preserves inherited custom bytes and absent baseline on repeat apply ${history ? "with" : "without"} legacy history`, () => {
      const root = inheritedTarget(CUSTOM_GUIDE, history);
      const row = guidePreview(root);
      assert.equal(row.state, "local-preserved");
      assert.equal(row.oldExpectedSha256, null);
      assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
      assert.equal(
        existsSync(join(root, STATE)),
        false,
        "preview must not publish history",
      );
      const output = apply(root);
      assert.match(output, /No new full-install receipt/u);
      assert.match(output, /--force-path/u);
      assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
      assert.equal(
        state(root).files.some((row) => row.path === GUIDE),
        false,
      );
      assert.equal(state(root).receipts.length, 0);
      const before = readFileSync(join(root, STATE), "utf8");
      apply(root);
      assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
      assert.equal(readFileSync(join(root, STATE), "utf8"), before);
    });
  }

  for (const flag of ["--force", "--force-managed"]) {
    it(`keeps inherited content under broad ${flag}`, () => {
      const root = inheritedTarget(CUSTOM_GUIDE, false);
      assert.equal(guidePreview(root, flag).state, "local-preserved");
      apply(root, flag);
      assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
      assert.equal(
        state(root).files.some((row) => row.path === GUIDE),
        false,
      );
    });
  }

  it("adopts only the named guide and then uses normal managed drift rules", () => {
    const root = inheritedTarget(CUSTOM_GUIDE, true);
    assert.equal(
      guidePreview(root, "--force-path", GUIDE).authority,
      "granted-path",
    );
    assert.match(
      apply(root, "--force-path", GUIDE),
      /Replaced local content: \.goat-flow\/learning-loop\/decisions\/README.md/u,
    );
    assert.equal(
      readFileSync(join(root, GUIDE), "utf8"),
      readFileSync(getTemplatePath(TEMPLATE), "utf8"),
    );
    assert.ok(state(root).files.some((row) => row.path === GUIDE));
    assert.equal(state(root).receipts.length, 1);
    writeFileSync(join(root, GUIDE), CUSTOM_GUIDE);
    assert.equal(guidePreview(root).state, "local-preserved");
    recordStaleBaselineHashes(root, "claude", [GUIDE]);
    const blocked = runCliInstaller(
      root,
      "--agent",
      "claude",
      "--dry-run",
      "--format",
      "json",
    );
    const row = JSON.parse(blocked.stdout).files.find(
      (file: { path: string }) => file.path === GUIDE,
    );
    assert.equal(row.state, "both-changed");
    const refused = runCliInstaller(root, "--agent", "claude");
    assert.notEqual(refused.status, 0);
    assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
  });

  it("preserves an inherited guide when a later package changes its template", () => {
    const root = inheritedTarget(CUSTOM_GUIDE, true);
    apply(root);
    const packageRoot = makeTempProject();
    for (const path of ["src", "workflow", "package.json"]) {
      assert.equal(existsSync(join(packageRoot, path)), false);
      cpSync(join(PROJECT_ROOT, path), join(packageRoot, path), {
        recursive: true,
        errorOnExist: true,
        force: false,
      });
    }
    symlinkSync(
      join(PROJECT_ROOT, "node_modules"),
      join(packageRoot, "node_modules"),
      process.platform === "win32" ? "junction" : "dir",
    );
    writeFileSync(
      join(packageRoot, TEMPLATE),
      readFileSync(getTemplatePath(TEMPLATE), "utf8") +
        "\nUpdated decision guidance.\n",
    );
    const before = readFileSync(join(root, STATE), "utf8");
    for (const flags of [["--dry-run", "--format", "json"], [], []]) {
      const result = spawnSync(
        "node",
        [
          "--import",
          "tsx",
          join(packageRoot, "src/cli/cli.ts"),
          "install",
          root,
          "--agent",
          "claude",
          ...flags,
        ],
        {
          cwd: packageRoot,
          encoding: "utf8",
          timeout: process.platform === "win32" ? 120_000 : 30_000,
        },
      );
      assert.equal(result.status, 0, result.stdout + result.stderr);
      if (flags.length) {
        const row = JSON.parse(result.stdout).files.find(
          (file: { path: string }) => file.path === GUIDE,
        );
        assert.equal(row.state, "local-preserved");
      }
      assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
      assert.equal(readFileSync(join(root, STATE), "utf8"), before);
    }
  });

  it("keeps existing unrelated rows and the stale receipt when the guide has no baseline", () => {
    const root = makeTempProject();
    apply(root);
    const before = state(root);
    before.files = before.files.filter((row) => row.path !== GUIDE);
    writeFileSync(join(root, STATE), canonicalManagedInstallStateBytes(before));
    writeFileSync(join(root, GUIDE), CUSTOM_GUIDE);
    apply(root);
    assert.deepEqual(state(root).files, before.files);
    assert.deepEqual(state(root).receipts, before.receipts);
    assert.equal(readFileSync(join(root, GUIDE), "utf8"), CUSTOM_GUIDE);
  });

  for (const guidePath of [GUIDE, LEGACY_GUIDE]) {
    it(`refuses direct Bash before mutation when an inherited guide exists at ${guidePath}`, () => {
      const root = inheritedTarget(CUSTOM_GUIDE, false, guidePath);
      const result = runInstaller(root, "--agent", "claude");
      assert.notEqual(result.status, 0);
      assert.match(result.stderr, /goat-flow install/u);
      assert.equal(readFileSync(join(root, guidePath), "utf8"), CUSTOM_GUIDE);
      assert.equal(existsSync(join(root, ".goat-flow/config.yaml")), false);
      assert.equal(existsSync(join(root, ".claude")), false);
    });
  }

  it("keeps malformed history blocking even for a recognised released guide", () => {
    const root = inheritedTarget(RELEASED_GUIDE, true);
    writeFileSync(
      join(root, ".goat-flow/state/install/claude.json"),
      "broken history",
    );
    const result = runCliInstaller(
      root,
      "--agent",
      "claude",
      "--force-path",
      GUIDE,
    );
    assert.notEqual(result.status, 0);
    assert.equal(readFileSync(join(root, GUIDE), "utf8"), RELEASED_GUIDE);
    assert.equal(existsSync(join(root, ".goat-flow/config.yaml")), false);
  });

  for (const guidePath of [GUIDE, LEGACY_GUIDE]) {
    it(`keeps unsafe guide paths blocking even with named authority at ${guidePath}`, (t) => {
      const root = makeTempProject();
      const outside = join(makeTempProject(), "guide.md");
      writeFileSync(outside, CUSTOM_GUIDE);
      mkdirSync(dirname(join(root, guidePath)), { recursive: true });
      if (!symlinkFileOrSkip(t, outside, join(root, guidePath))) return;
      const result = runCliInstaller(
        root,
        "--agent",
        "claude",
        "--force-path",
        GUIDE,
      );
      assert.notEqual(result.status, 0);
      assert.equal(readFileSync(outside, "utf8"), CUSTOM_GUIDE);
      assert.equal(existsSync(join(root, ".goat-flow/config.yaml")), false);
    });
  }
});
